local ActivityMysterySwitchCell = Class('ActivityMysterySwitchCell')

function ActivityMysterySwitchCell:__init()
	self.index = nil
	self.callBack = nil
end

function ActivityMysterySwitchCell:__delete()
	self.index = nil
	self.callBack = nil
	self.data = nil
end

function ActivityMysterySwitchCell:Awake()
	SetButtonAction(self.controller,Bind(self,self.OnSwitchCellClick))
	CfUtils.SetActive(self.ImgLight.gameObject, false)
end

function ActivityMysterySwitchCell:InitData(index,callBack)
	self.index = index
	self.callBack = callBack
	self.data = nil
end

function ActivityMysterySwitchCell:RefreshShow(data, nowFinishId, selectIndex)
	self.data = data
	self:UpdateNowFinishId(nowFinishId)
	self:RefreshStateShow()
	if self.index == selectIndex then
		self:OnSwitchCellClick()
	end
end

function ActivityMysterySwitchCell:UpdateNowFinishId(nowFinishId)
	self.nowFinishId = nowFinishId
end

function ActivityMysterySwitchCell:RefreshStateShow()
	local isUnLock = self:GetIsUnLock()
	CfUtils.SetActive(self.ImgLock.gameObject,not isUnLock)
	CfUtils.SetActive(self.ImgGet.gameObject, isUnLock)
	---抽完所有库存
	local isFinish = self:IsFinish()
	if isFinish and isUnLock then
		CfUtils.SetActive(self.ImgFinish.gameObject,true)
	else
		CfUtils.SetActive(self.ImgFinish.gameObject,false)
	end
end

function ActivityMysterySwitchCell:IsFinish()
	local stock = 0
	for i, v in pairs(self.data.rewards) do
		if v.stock > 0 then
			stock = stock + v.currentStock
		else
			stock = 99999
		end
	end
	return stock == 0
end

function ActivityMysterySwitchCell:OnSwitchCellClick()
	--local isUnLock = self:GetIsUnLock()
	--if isUnLock then
		if isNotNull(self.callBack) then
			self.callBack(self.index)
		end
	--end
end

function ActivityMysterySwitchCell:SetLightState(state)
	CfUtils.SetActive(self.ImgLight.gameObject,state)
end

function ActivityMysterySwitchCell:GetIsUnLock()
	return self.nowFinishId >= self.data.unlock
end

function ActivityMysterySwitchCell:OnDestroy()
	self.controller = nil--luabehaviour 中CSharp对象
	self:Delete()
end

return ActivityMysterySwitchCell